// Solution: OS scheduling logic
while (true) {
  // Give video editor most CPU time
  run_app(video_editor, 70%_cpu);

  // Run download when disk is free
  if (disk_idle) run_app(download, 100%_disk);

  // Music player gets leftover CPU
  run_app(music_player, 10%_cpu);
}
